    title: "인연의 결 — 총점을 내지 않는 이유",
    summary:
      "한 사람만 받고 상대 자리를 비운 채 가능한 값을 전부 대입합니다. 그렇게 얻은 유형에 총점을 붙이지 않는 이유를 밝힙니다.",
