    summary:
      "궁합은 다른 사람의 생년월일을 함께 넣는 서비스입니다. 두 사람의 입력값이 어디에도 기록되지 않는다는 말이 기술적으로 무슨 뜻인지, 결과 링크를 보낼 때 무엇이 함께 가는지 밝힙니다.",
